export interface LoanInput {
  amount: number;
  interestRate: number;
  years: number;
}

export interface YearlySchedule {
  year: number;
  balance: number;
  principalPaid: number;
  interestPaid: number;
  totalPayment: number;
}

:root {
  --primary-color: #2563eb;
  --primary-hover: #1d4ed8;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  padding: 20px;
}

.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 20px;
}

.header {
  text-align: center;
  margin-bottom: 32px;
}

.header h1 {
  font-size: 2rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 8px;
}

.header p {
  color: var(--text-muted);
  font-size: 1rem;
}

.calculator-layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 900px) {
  .calculator-layout {
    grid-template-columns: 400px 1fr;
  }
}

.form-section {
  background: var(--card-bg);
  padding: 24px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  border: 1px solid var(--border-color);
}

.chart-section {
  background: var(--card-bg);
  padding: 24px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  border: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.input-group {
  margin-bottom: 20px;
}

.input-group label {
  display: block;
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 8px;
  color: var(--text-main);
}

.input-group input {
  width: 100%;
  padding: 10px 14px;
  font-size: 1rem;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
  background-color: #fff;
}

.input-group input:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
}

.result-box {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
}

.result-item {
  background: var(--bg-color);
  padding: 16px;
  border-radius: 8px;
  border: 1px solid var(--border-color);
}

.result-item .label {
  font-size: 0.8125rem;
  color: var(--text-muted);
  margin-bottom: 4px;
}

.result-item .value {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--primary-color);
}

.btn-primary {
  display: inline-block;
  width: 100%;
  background-color: var(--primary-color);
  color: white;
  font-weight: 600;
  padding: 12px 16px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  font-size: 1rem;
  transition: background-color 0.2s;
  text-align: center;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

import { useState } from 'react';
import { LoanInput } from '../types';

interface LoanFormProps {
  initialValues: LoanInput;
  onSubmit: (values: LoanInput) => void;
}

export default function LoanForm({ initialValues, onSubmit }: LoanFormProps) {
  const [amount, setAmount] = useState(initialValues.amount);
  const [interestRate, setInterestRate] = useState(initialValues.interestRate);
  const [years, setYears] = useState(initialValues.years);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSubmit({
      amount: Number(amount),
      interestRate: Number(interestRate),
      years: Number(years),
    });
  };

  return (
    <form onSubmit={handleSubmit} className="form-section">
      <div className="input-group">
        <label htmlFor="amount">借入金額 (万円)</label>
        <input
          id="amount"
          type="number"
          value={amount}
          onChange={(e) => setAmount(Number(e.target.value))}
          min="1"
          step="10"
          required
        />
      </div>
      <div className="input-group">
        <label htmlFor="interestRate">金利 (%)</label>
        <input
          id="interestRate"
          type="number"
          value={interestRate}
          onChange={(e) => setInterestRate(Number(e.target.value))}
          min="0"
          max="20"
          step="0.01"
          required
        />
      </div>
      <div className="input-group">
        <label htmlFor="years">返済期間 (年)</label>
        <input
          id="years"
          type="number"
          value={years}
          onChange={(e) => setYears(Number(e.target.value))}
          min="1"
          max="50"
          required
        />
      </div>
      <button type="submit" className="btn-primary">
        計算する
      </button>
    </form>
  );
}

import { useState, useMemo } from 'react';
import LoanForm from './components/LoanForm';
import { LoanInput, YearlySchedule } from './types';
import {
  ResponsiveContainer,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  Legend,
  CartesianGrid,
} from 'recharts';

export default function App() {
  const [loanInput, setLoanInput] = useState<LoanInput>({
    amount: 3000,
    interestRate: 1.5,
    years: 30,
  });

  const { schedule, monthlyPayment, totalPayment, totalInterest } = useMemo(() => {
    const P = loanInput.amount * 10000;
    const r = loanInput.interestRate / 100 / 12;
    const n = loanInput.years * 12;

    let monthly = 0;
    if (r === 0) {
      monthly = P / n;
    } else {
      monthly = (P * r * Math.pow(1 + r, n)) / (Math.pow(1 + r, n) - 1);
    }

    const sched: YearlySchedule[] = [];
    let balance = P;
    let tPayment = 0;
    let tInterest = 0;

    for (let year = 1; year <= loanInput.years; year++) {
      let principalPaidYear = 0;
      let interestPaidYear = 0;

      for (let m = 0; m < 12; m++) {
        if (balance <= 0) break;
        const interestPaidMonth = balance * r;
        let principalPaidMonth = monthly - interestPaidMonth;
        if (principalPaidMonth > balance) {
          principalPaidMonth = balance;
        }
        balance -= principalPaidMonth;
        principalPaidYear += principalPaidMonth;
        interestPaidYear += interestPaidMonth;
      }

      tPayment += principalPaidYear + interestPaidYear;
      tInterest += interestPaidYear;

      sched.push({
        year,
        balance: Math.round(balance / 10000),
        principalPaid: Math.round(principalPaidYear / 10000),
        interestPaid: Math.round(interestPaidYear / 10000),
        totalPayment: Math.round((principalPaidYear + interestPaidYear) / 10000),
      });
    }

    return {
      schedule: sched,
      monthlyPayment: Math.round(monthly),
      totalPayment: Math.round(tPayment / 10000),
      totalInterest: Math.round(tInterest / 10000),
    };
  }, [loanInput]);

  return (
    <div className="app-container">
      <header className="header">
        <h1>住宅ローンシミュレーター</h1>
        <p>借入金額・金利・返済期間を入力して、毎月の返済額や返済推移を確認できます。</p>
      </header>

      <div className="calculator-layout">
        <LoanForm initialValues={loanInput} onSubmit={setLoanInput} />

        <div className="chart-section">
          <div className="result-box">
            <div className="result-item">
              <div className="label">毎月のご返済額</div>
              <div className="value">{monthlyPayment.toLocaleString()} 円</div>
            </div>
            <div className="result-item">
              <div className="label">総支払額</div>
              <div className="value">{totalPayment.toLocaleString()} 万円</div>
            </div>
            <div className="result-item">
              <div className="label">うち利息分</div>
              <div className="value">{totalInterest.toLocaleString()} 万円</div>
            </div>
          </div>

          <div style={{ width: '100%', height: 350 }}>
            <h3 style={{ fontSize: '1rem', fontWeight: 600, marginBottom: '12px' }}>
              年別返済内訳（元本 vs 利息）
            </h3>
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={schedule}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="year" unit="年" />
                <YAxis unit="万円" />
                <Tooltip formatter={(value: any) => [`${value} 万円`, '']} />
                <Legend />
                <Bar dataKey="principalPaid" name="元本返済" stackId="a" fill="var(--primary-color)" />
                <Bar dataKey="interestPaid" name="利息支払" stackId="a" fill="#93c5fd" />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
}
